export const meta = {
  name: 'stacked-fix-chain',
  description: 'Implement stacked fix PRs back to back: setup, sequential tasks, review, fix, full gate, push and open PR',
  phases: [
    { title: 'Setup' }, { title: 'Implement' }, { title: 'Review' }, { title: 'Fix' }, { title: 'Polish' }, { title: 'Gate' },
  ],
}
const SP = args.sp
const TARGET = `${SP}/target`
const RESULT = { type: 'object', properties: {
  status: { type: 'string', enum: ['done', 'blocked'] }, commit: { type: 'string' }, summary: { type: 'string' },
  tests: { type: 'string' }, deferred: { type: 'string' } }, required: ['status', 'summary', 'tests'] }
const REVIEW = { type: 'object', properties: {
  issues: { type: 'array', items: { type: 'object', properties: {
    severity: { type: 'string', enum: ['blocker', 'should-fix', 'nit'] }, file: { type: 'string' }, problem: { type: 'string' }, fix: { type: 'string' } },
    required: ['severity', 'problem', 'fix'] } },
  checks_run: { type: 'string' } }, required: ['issues', 'checks_run'] }
const GATE = { type: 'object', properties: {
  pushed: { type: 'boolean' }, pr_url: { type: 'string' }, gate: { type: 'string' }, fixes: { type: 'string' } }, required: ['pushed', 'gate'] }

function common(pr, wt) {
  return `
Worktree: ${wt} (branch ${pr.branch}, base ${pr.base}). Work ONLY there: cd into it in every Bash call. Never touch /Users/gabe/Projects/callisto (other sessions use it).
Build: prefix cargo with CARGO_TARGET_DIR=${TARGET}. You are the only agent building; one cargo command at a time, scoped (cargo test -p <crate> [filter], cargo clippy -p <crate> --all-targets -- -D warnings; cargo nextest available).
Context: docs/projects/ROAD-TO-V1.md section "${pr.section}" (plan and owner decisions), ${pr.specs.join(', ')}, .claude/semantic-model/INDEX.md and its topic files, docs/adr/README.md.
Rules: AGENTS.md applies (format-preserving edits, atomic_write, miette code + help on user-facing errors, grep for sibling defects and fix them in the same change, code never cites specs, comments are one short line for a non-obvious why, wrapped at 120 columns, never history (\"used to\", \"previously\")). Update the spec criteria that change in the same commit (current behavior only, no history). Remove each roadmap bullet this change completes. ${pr.adr ? `This PR adds one ADR: ${pr.adr}. Write it in docs/adr following docs/adr/README.md with an existing ADR as the template (sourced reasons only, options considered, enforcement, revisit when; Status: Proposed) and add its index line.` : 'This PR adds no ADR.'}
Commit: conventional message explaining why; no trailers, no session links, no Co-Authored-By. Add a changeset first when user-visible: \`CARGO_TARGET_DIR=${TARGET} cargo run -q -p callisto-cli -- add --package callisto-cli:patch --summary "..."\` once per user-visible topic, written as the changelog entry: what the user now sees, no internal names or mechanism.
Evaluation fixtures: ${SP}/repro/<name>.`
}

const out = []
for (const pr of args.prs) {
  const wt = `${SP}/${pr.wt}`
  const C = common(pr, wt)
  let results = [], review = null
  if (pr.tasks && pr.tasks.length) {
  phase('Setup')
  await agent(`Run: cd /Users/gabe/Projects/callisto && git worktree add -b ${pr.branch} ${wt} ${pr.base}. If the branch or path already exists, reuse it (git worktree list) as long as it is based on ${pr.base}. Report the resulting HEAD.`,
    { label: `setup:${pr.key}`, phase: 'Setup', model: 'haiku', effort: 'low' })
  phase('Implement')
  for (const [i, t] of pr.tasks.entries()) {
    const r = await agent(`${C}\nPR ${pr.key}, task ${i + 1}/${pr.tasks.length}: ${t.title}\n${t.detail}\n\nDone when: the fix is in, a test fails without it and passes with it, scoped tests and clippy pass for touched crates, and one commit is made. If part of the task is wrong on inspection, say so in 'deferred' instead of forcing it.`,
      { label: `${pr.key}:${t.key}`, phase: 'Implement', agentType: 'smith:implementer', schema: RESULT })
    results.push({ key: t.key, ...(r || { status: 'blocked', summary: 'agent died', tests: '' }) })
    log(`${pr.key}/${t.key}: ${r ? r.status : 'died'}`)
  }
  phase('Review')
  review = await agent(`${C}\nReview \`git -C ${wt} diff ${pr.base}...HEAD\` for PR ${pr.key} ("${pr.section}"). Implementer reports:\n${JSON.stringify(results, null, 1)}\nCheck each roadmap item for this PR is fixed (reproduce with a fixture or test), no sibling left, spec criteria match, tests would fail without the fix, no scope creep, no false claims in docs/ADR. ACTUALLY RUN cargo clippy -D warnings and cargo nextest run -p for each touched crate; report real output. Do not edit files.`,
    { label: `${pr.key}:review`, phase: 'Review', agentType: 'smith:reviewer', schema: REVIEW })
  const todo = (review?.issues || []).filter(x => x.severity !== 'nit')
  if (todo.length) {
    phase('Fix')
    await agent(`${C}\nAddress these review findings in commits on ${pr.branch}:\n${JSON.stringify(todo, null, 1)}\nReject a finding only with evidence.`,
      { label: `${pr.key}:fix`, phase: 'Fix', agentType: 'smith:implementer', schema: RESULT })
  }
  }
  phase('Polish')
  await agent(`${C}\nPolish PR ${pr.key} before its gate. (1) Comments: for every comment line this branch added or changed (\`git diff ${pr.base}...HEAD -- '*.rs'\`, +// +/// +//!): delete ones that restate code, function or test names; keep one line for a non-obvious why (two or three for public doc comments); no history ("used to", "previously", "before the fix", "no longer"); fill up to 120 columns; no emphasis. Never change code. (2) Changesets this branch added (.changeset/*.md except README.md): exactly one per user-visible topic, frontmatter \`callisto-cli: patch\` (or minor for a new capability), text written as the changelog entry a CLI user reads: what they now see, no internal type, module or mechanism names; merge changesets of one topic; delete changesets for internal-only changes. (3) Any TODO comment this branch added for a deferred sibling defect: remove it and add a bullet in docs/projects/ROAD-TO-V1.md under the right PR section instead. (4) New diagnostic codes this branch added must appear in docs/errors.md. Run cargo fmt --all only (no builds), then commit "chore: changelog-ready changesets and succinct comments".`,
    { label: `${pr.key}:polish`, phase: 'Polish', model: 'sonnet' })
  phase('Gate')
  const gate = await agent(`${C}\nFinal gate for PR ${pr.key}. In ${wt}, with CARGO_TARGET_DIR=${TARGET}, run in order and fix any failure (commit fixes): cargo fmt --all --check; cargo nextest run --workspace --no-fail-fast; cargo test --workspace --doc; cargo clippy --workspace --all-targets -- -D warnings; just workflow-contracts. When all pass: git push -u origin ${pr.branch}, then open the PR: gh pr create --base ${pr.base} --head ${pr.branch} --label bug --title "${pr.title}" --body "<body>". Body: first line "Stacked on ${pr.basePr}. ${pr.section} (docs/projects/ROAD-TO-V1.md)."; then one bullet per fix saying what was wrong and what changed (verify each claim against the diff; do not describe tests that do not exist); a "Verification:" line with the real counts; a "Not in this PR:" line for anything deferred. Succinct, no hard-wrapped lines, no emojis, no session links. Return pushed, pr_url, gate results, and fixes made.`,
    { label: `${pr.key}:gate`, phase: 'Gate', schema: GATE })
  out.push({ pr: pr.key, results, review: review && { issues: review.issues.length }, gate })
  log(`${pr.key}: ${gate?.pr_url || 'no PR'}`)
  if (!gate?.pushed) { log(`stopping chain: ${pr.key} did not pass the gate`); break }
}
return out

