fn github_release_id_once(
    root: &Path,
    runner: &dyn CommandRunner,
    repository: &str,
    tag: &TagName,
) -> Result<Attempt<ReleaseIdLookup>, GraphError> {
    let (owner, name) = repository
        .split_once('/')
        .ok_or_else(|| malformed_github_response("graphql", "GitHub repository is not OWNER/NAME"))?;
