  [ -f "$lag" ] || return 1
  left=$(cat "$lag")
  [ "$left" -gt 0 ] || return 1
  printf '%s' $((left - 1)) > "$lag"
}
gh_graphql() {
  tag=''
  for a in "$@"; do
    case "$a" in tagName=*) tag=${a#tagName=} ;; esac
  done
  if [ "$(forge_state)" = absent ] || [ "$tag" != "$CALLISTO_TEST_FORGE_TAG" ] || lagging; then
